<script setup>
import{formatMXN}from'~~/shared/features/pricing/prices.js'
const props=defineProps({orderId:{type:String,required:true},returnedFromCancel:Boolean})
const data=ref(null),busy=ref(false),failure=ref('')
const labels={PENDING:'Pendiente',PAID:'Pagado',FAILED:'No pagado; puedes revisar el intento',NOT_REQUIRED:'Sin cobro requerido',RECONCILING:'En revisión; no reintentes una compra distinta',PARTIALLY_REFUNDED:'Reembolso parcial',REFUNDED:'Reembolsado'}
async function consult(){busy.value=true;failure.value='';try{data.value=await $fetch('/api/payments/status',{method:'POST',body:{orderId:props.orderId}})}catch(e){failure.value=e.data?.statusMessage??'No pudimos consultar el pedido.'}finally{busy.value=false}}
async function cancel(){if(busy.value)return;busy.value=true;failure.value='';try{await $fetch('/api/payments/cancel',{method:'POST',body:{orderId:props.orderId}});await consult()}catch(e){failure.value=e.data?.statusMessage??'No pudimos cerrar el intento. Consulta su estado.'}finally{busy.value=false}}
async function resume(){if(busy.value)return;busy.value=true;failure.value='';try{const result=await $fetch('/api/payments/start',{method:'POST',body:{orderId:props.orderId,acceptedTotalCents:data.value.totalMoneyCents}});if(result.url)await navigateTo(result.url,{external:true});else await consult()}catch(e){failure.value=e.data?.statusMessage??'No pudimos reanudar el pago.'}finally{busy.value=false}}
onMounted(consult)
</script>
<template><section class="mx-auto max-w-store px-4 py-12 md:px-8"><UiBreadcrumbs :items="[{label:'Estado del pago'}]"/><h1 class="text-display-l font-bold">Estado del pago</h1><p class="mt-4">El estado se consulta en el servidor; volver de Stripe no confirma por sí solo una compra.</p><p v-if="returnedFromCancel" class="mt-3">Regresaste desde el pago. Puedes consultar, reanudar o cerrar el intento.</p><p v-if="failure" role="alert" class="mt-4 text-crit">{{failure}}</p><p v-if="busy" role="status" class="mt-4">Consultando…</p><div v-if="data" class="mt-6"><p>Pedido {{data.number}}</p><p class="font-mono">{{formatMXN(data.totalMoneyCents)}} {{data.currency}}</p><p role="status">Pago: {{labels[data.moneyStatus]??data.moneyStatus}}</p><p v-if="data.cardRejected" role="alert" class="mt-3 text-crit">Stripe informó un pago rechazado. Puedes reanudar la sesión para intentarlo de nuevo dentro del plazo.</p><p>Pedido: {{data.status==='CONFIRMED'?'Confirmado':data.status==='PENDING_PAYMENT'?'Pendiente de pago':data.status}}</p><p v-if="data.expiresAt" class="mt-3">Plazo del intento: {{data.expiresAt}}</p><div v-if="data.status==='PENDING_PAYMENT'" class="mt-4 flex flex-wrap gap-3"><UiButton :disabled="busy" @click="resume">Reanudar o reintentar pago</UiButton><UiButton variant="secondary" :disabled="busy" @click="cancel">Cerrar intento sin confirmar compra</UiButton></div></div><UiButton class="mt-6" variant="secondary" :disabled="busy" @click="consult">Actualizar estado</UiButton><NuxtLink to="/carrito" class="ml-4 inline-flex min-h-11 items-center text-accent-text underline">Volver al carrito</NuxtLink></section></template>
